using System;using System.Collections.Generic;using System.IO;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using SolidWorks.Interop.sldworks;using SolidWorks.Interop.swconst;
namespace Marvilon.K01.BomProjection { class Row{public string part_no{get;set;}public string description{get;set;}public string unit{get;set;}public string make_buy{get;set;}public string material_authority{get;set;}public string material_status{get;set;}public string release{get;set;}public string path{get;set;}} class Bom{public string status{get;set;}public List<Row> rows{get;set;}} class Item{public string part_no="";public string path="";public string action="";public string status="";public string error="";} class Rep{public string schema="k01_bom_property_projection_v1";public string created_utc=DateTime.UtcNow.ToString("o");public string mode="DRY_RUN";public string status="RUNNING";public string solidworks_revision="";public List<Item> items=new List<Item>();public string error="";}
class Program{static SldWorks sw;static Rep r=new Rep();static string repo=@"D:\BreshevEngineering\marvilon-k01";static string src,report;static bool apply=false;static int Main(string[] args){try{apply=args.Length>0&&args[0].Equals("--apply",StringComparison.OrdinalIgnoreCase);r.mode=apply?"APPLY":"DRY_RUN";src=Path.Combine(repo,"reports","bom","K01_BOM_RECONCILIATION_study_c2r1.json");report=Path.Combine(repo,"reports","bom","K01_BOM_PROPERTY_PROJECTION_CURRENT.json");Bom b=new JavaScriptSerializer().Deserialize<Bom>(File.ReadAllText(src));if(b==null||b.rows==null)throw new Exception("invalid reconciliation");Connect();foreach(Row x in b.rows)Do(x);r.status=r.items.Exists(i=>i.status.StartsWith("FAIL"))?"HOLD":"PASS_"+r.mode;Save();return r.status.StartsWith("PASS")?0:2;}catch(Exception ex){r.status="FAIL";r.error=ex.ToString();try{Save();}catch{}Console.Error.WriteLine(ex);return 1;}}
static void Do(Row x){Item it=new Item{part_no=x.part_no,path=x.path,action=apply?"WRITE_TEXT_PROPERTIES":"WOULD_WRITE_TEXT_PROPERTIES"};r.items.Add(it);try{if(String.IsNullOrWhiteSpace(x.path)||!File.Exists(x.path)){it.status="FAIL_MISSING_FILE";return;}if(!apply){it.status="PASS_DRY_RUN";return;}string backupRoot=Path.Combine(@"D:\Marvilon\K01\cad\property_backups",DateTime.Now.ToString("yyyyMMdd"));Directory.CreateDirectory(backupRoot);string bak=Path.Combine(backupRoot,Path.GetFileNameWithoutExtension(x.path)+"_"+DateTime.Now.ToString("HHmmss")+Path.GetExtension(x.path));File.Copy(x.path,bak,true);int e=0,w=0;ModelDoc2 d=sw.OpenDoc6(x.path,(int)swDocumentTypes_e.swDocPART,(int)swOpenDocOptions_e.swOpenDocOptions_Silent,"",ref e,ref w) as ModelDoc2;if(d==null){it.status="FAIL_OPEN";it.error="OpenDoc6 "+e;return;}string t=d.GetTitle();try{Set(d,"PartNo",x.part_no);Set(d,"Description",x.description);Set(d,"MaterialSpec",x.material_authority);Set(d,"MaterialStatus",x.material_status);Set(d,"MakeBuy",x.make_buy);Set(d,"Unit",x.unit);Set(d,"LifecycleStatus",x.release);Set(d,"K01_ControlRevision","C2R1-PR1");int se=0,swarn=0;bool ok=d.Save3((int)swSaveAsOptions_e.swSaveAsOptions_Silent,ref se,ref swarn);if(!ok||se!=0)throw new Exception("Save3 errors="+se);it.status="PASS_APPLIED";}finally{try{sw.CloseDoc(t);}catch{}}}catch(Exception ex){it.status="FAIL_EXCEPTION";it.error=ex.Message;}}
static void Set(ModelDoc2 d,string k,string v){CustomPropertyManager c=d.Extension.get_CustomPropertyManager("");try{c.Delete2(k);}catch{}int q=c.Add(k,"Text",v??"");if(q==0)try{c.Set2(k,v??"");}catch{}}
static void Connect(){object o=null;try{o=Marshal.GetActiveObject("SldWorks.Application");}catch{}sw=o!=null?(SldWorks)o:(SldWorks)Activator.CreateInstance(Type.GetTypeFromProgID("SldWorks.Application",true));sw.Visible=true;r.solidworks_revision=sw.RevisionNumber();}
static void Save(){Directory.CreateDirectory(Path.GetDirectoryName(report));File.WriteAllText(report,new JavaScriptSerializer().Serialize(r));}}
